// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bool status) public {
        // Ensure caller is not address(0) to avoid edge cases with mapping
        vm.assume(caller != address(0));
        // Set the caller as approved logger with the given status
        vm.prank(address(0)); // owner is address(0) by default
        c.setApprovedLogger(caller, status);
        // Assert that approvedToLog returns the same status we set
        assertTrue(c.approvedToLog(caller) == status);
    }
}

